const fs = require('fs');
const path = require('path');
const wikiRoot = 'G:/AI/AIMemory/wiki';
const dirs = ['concepts', 'lessons', 'tasks', 'queries', 'references'];
const validSlugs = new Set();
for (const d of dirs) {
  const dp = path.join(wikiRoot, d);
  if (!fs.existsSync(dp)) continue;
  for (const f of fs.readdirSync(dp)) {
    if (f.endsWith('.md')) validSlugs.add(f.replace(/\.md\$/, ''));
  }
}
let brokenCount = 0;
for (const d of dirs) {
  const dp = path.join(wikiRoot, d);
  if (!fs.existsSync(dp)) continue;
  for (const f of fs.readdirSync(dp)) {
    if (!f.endsWith('.md')) continue;
    const content = fs.readFileSync(path.join(dp, f), 'utf8');
    const links = [...content.matchAll(/\[\[([^\]|]+)(\|[^\]]*)?\]\]/g)].map(m => m[1].trim());
