check(d1.gap.missingCommands.length === facts.commands.length - 2,
  `少 ${facts.commands.length - 2} 個指令被抓到（實得 ${d1.gap.missingCommands.length}）`);
check(d1.gap.missingCommands.includes("moa"), "/moa 被列為缺漏");

console.log("\n[2] 偵測缺漏 dream 步驟");
const d2 = diffDoc("fake.md", "步驟：sharedsync → dailylog → restart", facts);
check(d2.gap.missingDreamSteps.includes("specialistreflect"), "specialistreflect 被列為缺漏");
