check(!d3.gap.missingCommands.includes("memorytoskill"), "/MemoryToSkill 對上 memorytoskill");
check(!d3.gap.missingCommands.includes("refreshrouting"), "/refresh-routing 對上 refreshrouting");

console.log("\n[4] 可疑步驟：文件多寫，只回報不刪");
