check(d4.suspicious.missingDreamSteps.includes("ghoststep"), "ghoststep 被列為可疑");
check(d4.gap.missingDreamSteps.length > 0, "同時仍回報真正的缺漏");

console.log("\n[5] 抽取脫鉤必須 throw（不可靜默回報「已是最新」）");
