const log = (t) => (d) => d.toString().split("\n").filter(s => s.includes("[pet]")).forEach(s => console.log(t, s.trim()));
child.stdout.on("data", log("[out]")); child.stderr.on("data", log("[err]"));
const cleanup = () => { try { execSync(`taskkill /T /F /PID ${child.pid}`, { stdio: "ignore" }); } catch {} };
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
try {
