  const page = targets?.find(t => t.type === "page");
  if (!page) { console.log("CDP 沒起來"); cleanup(); process.exit(1); }
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise(r => ws.on("open", r));
  const evaluate = (expr) => new Promise(resolve => {
    const id = Math.floor(Math.random() * 1e6);
    const onMsg = (raw) => { const m = JSON.parse(raw.toString()); if (m.id !== id) return;
      ws.off("message", onMsg); resolve(m.result?.result?.value); };
    ws.on("message", onMsg);
    ws.send(JSON.stringify({ id, method: "Runtime.evaluate", params: { expression: expr, returnByValue: true } }));
  });
  const read = () => evaluate(`(() => { const el = document.getElementById('background-jobs');
    return JSON.stringify({ text: el.textContent, cls: el.className }); })()`);
  await sleep(2000);
  console.log("連上當下（修正前這裡是空的）:", await read());
  await sleep(5000);
  console.log("T+5s（沒有任何變更事件）:", await read());
  ws.close();
} finally { cleanup(); }
process.exit(0);
