/**
 * @ch 附掛在已開著的 Preview 上連續取樣（不自己開 Chrome、不送任何輸入）。
 * @description 用法：node docs/preview-watch.mjs [分鐘數]
 *   前提：preview-vs-probe.mjs --keep 已經裝好 window.__probe 並把視窗留著。
 *   盤面／飛行體／隱藏格／VS 結果一有變化就印一行。
 */
const minutes = Number( process.argv[ 2 ] ?? 10 );
const list = await ( await fetch( "http://127.0.0.1:9222/json/list" ) ).json();
const target = list.find( t => t.type === "page" && t.url.includes( "7456" ) );
if ( !target ) { console.log( "找不到 preview 分頁" ); process.exit( 1 ); }

const socket = new WebSocket( target.webSocketDebuggerUrl );
const pending = new Map();
let id = 1;
socket.addEventListener( "message", e => { const m = JSON.parse( e.data ); pending.get( m.id )?.( m ); pending.delete( m.id ); } );
await new Promise( r => socket.addEventListener( "open", r, { once: true } ) );
const send = ( method, params = {} ) => new Promise( r => { pending.set( id, r ); socket.send( JSON.stringify( { id: id++, method, params } ) ); } );
await send( "Runtime.enable" );

const Eval = async expr => {
    const out = await send( "Runtime.evaluate", { expression: `(() => { try { return (${expr.trim()}); } catch ( e ) { return { __error: String( e ) } } })()`, returnByValue: true, awaitPromise: true } );
    return out.result?.result?.value;
};

const SAMPLE = `( () => {
    if ( !window.__probe ) return { __noprobe: true };
    const board = window.__probe.Snapshot();
    const gv = window.__probe.gv;
    return {
        reels: board.map( c => c.map( cell => {
            const symbol = ( cell.frame || "?" ).replace( "Symbol_", "" );
            return cell.active === false ? "[" + symbol + "]" : symbol;
        } ).join( "," ) ),
        labels: board.map( ( c, i ) => i + ">" + c.map( cell => cell.label || "" ).join( "|" ) ).filter( s => s.replace( /\\|/g, "" ).length > 2 ),
        fly: window.__probe.FlyNodes(),
        hidden: window.__probe.HiddenCells(),
        y: board[ 0 ].map( cell => cell.y ),
        vs: ( gv.VsFeatureResult?.steps || [] ).map( s => s.reelIndex + ":" + s.vsType + ":" + s.winningMultiplier ),
        omen: gv.IsMgOmen,
    };
} )()`;

console.log( `[watch] 取樣 ${minutes} 分鐘，有變化才印。` );
let last = "";
const deadline = Date.now() + minutes * 60 * 1000;
while ( Date.now() < deadline )
{
    const sample = await Eval( SAMPLE ).catch( () => null );
    if ( sample )
    {
        const key = JSON.stringify( sample );
        if ( key !== last )
        {
            console.log( `[t=${new Date().toISOString().slice( 11, 19 )}] ${key}` );
            last = key;
        }
    }
    await new Promise( r => setTimeout( r, 120 ) );
}
console.log( "[watch] 結束" );
process.exit( 0 );
EOF
